#include "core.hpp"
#include <iostream>
#include <iomanip>
using namespace rb;
struct WithoutWidth{uint64_t id;uint32_t owner,vb,vc;Pose p;F rest;uint8_t seed,depth,state,pad;};
static_assert(sizeof(WithoutWidth)==sizeof(Node));
World small_world(bool tiny,int count=3){World w;w.materials.push_back({std::numeric_limits<float>::infinity(),.1f,0,uint32_t(count),1,false});w.pieces.push_back({0,42,{},{}});std::vector<Poly>polys=tiny?std::vector<Poly>{{{0,0},{.005,0},{.005,.005},{0,.005}},{{.005,0},{2,0},{2,1},{.005,1}}}:std::vector<Poly>{{{0,0},{1,0},{1,1},{0,1}}};for(size_t i=0;i<polys.size();++i){Node n;n.id=i+1;n.seed=42;n.vb=w.vertices.size();n.vc=polys[i].size();n.rest=centroid(polys[i]);n.p.x=n.rest.x;n.p.y=n.rest.y;n.cached_width=width(polys[i]);w.vertices.insert(w.vertices.end(),polys[i].begin(),polys[i].end());w.pieces[0].members.push_back(w.source.size());w.source.push_back(n);}if(tiny){auto a=w.source[0],b=w.source[1];auto s=shared(w.outline(a),w.outline(b));w.pieces[0].edges.push_back({0,1,s.point,{s.point-a.rest,s.point-b.rest}});}return w;}
void require(bool b,const char*m){if(!b)throw std::runtime_error(m);}
int location(V p,Outline poly){bool in=false;for(size_t i=0;i<poly.size();++i){V a=poly[i],b=poly[(i+1)%poly.size()],d=b-a;double len=length(d);if(len>0&&std::abs(cross(d,p-a))/len<1e-8&&dot(p-a,p-b)<=1e-12)return 0;if((a.y>p.y)!=(b.y>p.y)){double x=a.x+(p.y-a.y)*(b.x-a.x)/(b.y-a.y);if(p.x<x)in=!in;}}return in?1:-1;}
void partition_audit(const World&w,const Work<AoS>&v){for(uint32_t i=0;i<v.nodes.size();++i){if(v.nodes.get(i).state!=Split)continue;auto t=v.tree[i];auto parent=v.outline(w,v.nodes.get(i));for(size_t a=t.cb;a<t.cb+t.cc;++a){auto pa=v.outline(w,v.nodes.get(v.children[a]));for(V p:pa)require(location(p,parent)>=0,"child escaped its parent outline");for(size_t b=a+1;b<t.cb+t.cc;++b){auto pb=v.outline(w,v.nodes.get(v.children[b]));for(size_t k=0;k<pa.size();++k)for(size_t l=0;l<pb.size();++l)require(!proper_intersect(pa[k],pa[(k+1)%pa.size()],pb[l],pb[(l+1)%pb.size()]),"children have crossing boundaries");for(auto&tri:triangles(pa)){V mid=(tri[0]+tri[1]+tri[2])*(1.0/3);require(location(mid,pb)!=1,"children overlap in area");}}}}}

int main(){try{Templates input=read_templates("inputs/templates.txt");{World w=make_world(input,512,0,true);auto a=make_store<AoS>(w);auto p=make_store<PoseFirst>(w);auto h=make_store<HotCold>(w);auto c=make_store<Columns>(w);std::vector<int>members(w.source.size());for(size_t owner=0;owner<w.pieces.size();++owner)for(auto row:w.pieces[owner].members){require(w.source[row].owner==owner,"bad membership owner");++members[row];}uint64_t reference=0,columns=0,packed=0;for(size_t i=0;i<w.source.size();++i){Node x=w.source[i];require(members[i]==1,"bad member coverage");for(Node y:{a.get(i),p.get(i),h.get(i),c.get(i)}){require(x.id==y.id&&x.owner==y.owner&&x.vb==y.vb&&x.vc==y.vc&&x.p.x==y.p.x&&x.p.y==y.p.y&&x.p.c==y.p.c&&x.p.s==y.p.s&&x.p.vx==y.p.vx&&x.p.vy==y.p.vy&&x.p.w==y.p.w&&x.rest.x==y.rest.x&&x.rest.y==y.rest.y&&x.cached_width==y.cached_width&&x.seed==y.seed,"store field mismatch");}auto owner=x.owner;Blast b{{-3.8f+16.f*float(owner%128),.2f+16.f*float(owner/128)},5.8f};float strength=w.materials[w.pieces[owner].material].subdivision_strength;if(fails(load(b,{x.p.x,x.p.y}),strength))reference+=hash64(x.id);if(fails(load(b,c.position(i)),strength))columns+=hash64(c.id(i));}for(size_t owner=0;owner<w.pieces.size();++owner){Blast b{{-3.8f+16.f*float(owner%128),.2f+16.f*float(owner/128)},5.8f};float strength=w.materials[w.pieces[owner].material].subdivision_strength;for(auto row:w.pieces[owner].members)if(fails(load(b,a.position(row)),strength))packed+=hash64(a.id(row));}require(reference==columns&&reference==packed,"whole-world query outputs differ");}{World w=small_world(true);auto s=make_store<AoS>(w);Work<AoS>v;Options o;run_event(w,s,0,{{-.2,.0025},.3f},o,.08f,v);validate(w,v);require(v.nodes.size()==2&&v.stats.generated==0&&v.final.size()==1&&v.final[0].id==2,"thin attached subdivision must remove directly");}{World w=small_world(false,1);auto s=make_store<AoS>(w);Work<AoS>v;Options o;run_event(w,s,0,{{-.2,.5},2.f},o,.08f,v);require(v.nodes.size()==1&&v.stats.generated==0&&v.final.empty(),"no-progress generation must not clone");}
 std::ofstream out("results/seed_policy_audit.csv");out<<"template,refinements,mixed_width_batches,small_children_with_nonzero_seed,small_children_that_split,zero_seed_live_nodes,maximum_impulse_error\n";for(size_t ti=0;ti<12;++ti){World w=make_world(input,1,ti,false);auto s=make_store<AoS>(w);Work<AoS>v;Options o;Blast blast{{-3.8,.2},6.2f};run_event(w,s,0,blast,o,.18f,v);validate(w,v);partition_audit(w,v);std::vector<int>parent(v.nodes.size(),-1);size_t mixed=0,small_nonzero=0,small_split=0;for(uint32_t i=0;i<v.nodes.size();++i){Node n=v.nodes.get(i);if(n.state!=Split)continue;Tree t=v.tree[i];float lo=1e30f,hi=0;for(size_t k=t.cb;k<t.cb+t.cc;++k){uint32_t row=v.children[k];parent[row]=i;Node child=v.nodes.get(row);lo=std::min(lo,child.cached_width);hi=std::max(hi,child.cached_width);if(child.cached_width<=.18f&&child.seed){++small_nonzero;small_split+=child.state==Split;}}mixed+=lo<=.18f&&hi>.18f;}require(small_split==0,"shared batch flag bypassed individual cutoff");double error=0;for(auto f:v.final){uint32_t r=f.row;while(parent[r]>=0)r=parent[r];Node root=v.nodes.get(r),n=v.nodes.get(f.row);V d=V{n.p.x,n.p.y}-blast.p;float len=length(d),dv=load(blast,{n.p.x,n.p.y})*.1f;double ex=root.p.vx-root.p.w*(n.p.y-root.p.y),ey=root.p.vy+root.p.w*(n.p.x-root.p.x);if(len>1e-8){ex+=d.x/len*dv;ey+=d.y/len*dv;}error=std::max({error,std::abs(f.vx-ex),std::abs(f.vy-ey)});}require(error<2e-5,"blast impulse applied more than once or inherited motion wrong");Work<AoS>untouched;run_event(w,s,0,{{-100,-100},1.f},o,.18f,untouched);require(untouched.final.size()==w.source.size(),"unloaded seed-zero geometry was removed");Work<AoS>next;Options one;one.recursive=false;run_event(w,s,0,{{-3.8,.2},100.f},one,.18f,next);validate(w,next);partition_audit(w,next);out<<ti<<','<<v.stats.refinements<<','<<mixed<<','<<small_nonzero<<','<<small_split<<','<<(w.pieces[0].seed==0?untouched.final.size():0)<<','<<std::setprecision(12)<<error<<'\n';}for(size_t ti:{0U,1U,2U}){World fixture=make_world(input,1,ti,false);Poly parent=hull(fixture.vertices);World w;w.materials=fixture.materials;w.materials[ti].subdivision_strength=0;w.pieces.push_back({uint32_t(ti),1,{0},{}});w.vertices=parent;Node n;n.id=1;n.seed=1;n.vc=parent.size();n.rest=centroid(parent);n.p.x=n.rest.x;n.p.y=n.rest.y;n.cached_width=width(parent);w.source.push_back(n);auto s=make_store<AoS>(w);Work<AoS>v;Options one;one.recursive=false;run_event(w,s,0,{{-3.8,.2},100.f},one,.18f,v);validate(w,v);partition_audit(w,v);}for(size_t ti:{0U,1U,2U})for(auto cfg:std::array<std::pair<float,float>,2>{{{6.5f,.09f},{12.f,.18f}}}){World w=make_world(input,1,ti,false);auto s=make_store<AoS>(w);Work<AoS>v;Options o;run_event(w,s,0,{{-3.8,.2},cfg.first},o,cfg.second,v);validate(w,v);partition_audit(w,v);}std::cerr<<"layout, selection, partition, terminal, mixed-batch and single-impulse audits passed\n";
 }catch(std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
